CREATE TABLE IF NOT EXISTS uvs_states (project_id TEXT PRIMARY KEY, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS uvs_tasks (task_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS uvs_artifacts (artifact_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS uvs_lessons (id BIGSERIAL PRIMARY KEY, project_id TEXT NOT NULL, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS uvs_page_profiles (page_id TEXT PRIMARY KEY, payload JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS uvs_jobs (job_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, status TEXT NOT NULL, payload JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS uvs_telegram_state (key TEXT PRIMARY KEY, value TEXT NOT NULL);
